INSERT INTO notes (title, body, color, views, created_at, updated_at) VALUES
('Почему Crystal', E'Один бинарник, миллисекунды старта и ноль GC-пауз в проде.\n\nCRails переносит конвенции Rails в компилируемый мир: те же модели, те же шаблоны, тот же router — но всё это уходит в native-код.', 'violet', 128, '2026-09-28 10:00:00', '2026-09-28 10:00:00'),
('Стек демо-приложения', E'Эта страница прошла весь стек: railties поднял сервер, action_pack сматчил роут, active_record достал запись из PostgreSQL, а action_view отрендерил ERB-шаблон с партиалами.', 'sky', 96, '2026-09-29 12:30:00', '2026-09-29 12:30:00'),
('Валидации как в Rails', E'Заголовок обязателен и не длиннее 140 символов — это обычный validates в модели. Попробуйте сохранить пустую форму: ошибки покажет тот же механизм, что и в оригинале.', 'emerald', 64, '2026-09-30 09:15:00', '2026-09-30 09:15:00'),
('Счётчик просмотров', E'Каждое открытие заметки делает UPDATE notes SET views = views + 1 — цифра внизу карточки живая.', 'amber', 42, '2026-10-01 18:45:00', '2026-10-01 18:45:00'),
('Flash-сообщения', E'Создайте или удалите заметку — зелёный баннер сверху это flash из cookies, совсем как в Rails.', 'rose', 31, '2026-10-02 14:20:00', '2026-10-02 14:20:00'),
('Что дальше', E'Дальше по плану: PG-очереди, кэш, pubsub и devise-аутентификация для полноценных приложений.', 'sky', 12, '2026-10-03 08:00:00', '2026-10-03 08:00:00');
